        if proxy_host:
            proxies = get_proxy_dict(proxy_host, proxy_port, proxy_protocol)

        session, session_data = build_client_session(
            api_key=api_key,
            proxies=proxies,
            headers={}
        )

        if not hasattr(ctx, 'obj') or ctx.obj is None:
            ctx.obj = SafetyContext()

        ctx.obj.session = session

        return func(*args, **kwargs)

    return wrapper
